// ---------- Settings ----------
// Keyword weights: specific interests count more than generic buzzwords.
const KEYWORDS = {
  'docker': 3, 'kubernetes': 3, 'k8s': 3, 'container': 3, 'containers': 3,
  'vulnerability': 3, 'vulnerabilities': 3, 'cve': 3, 'exploit': 3, 'zero-day': 3,
  'security': 2, 'rust': 2, 'linux': 2, 'open source': 2, 'open-source': 2,
  'python': 2, 'typescript': 2, 'claude': 2,
  'ai': 1, 'llm': 1, 'llms': 1, 'openai': 1,
};

const HALF_LIFE_HOURS = 12;   // a story loses half its freshness every 12 hours
const MISSING_DATE_HOURS = 24; // treat stories without a date as a day old
const BUZZ_PER_SOURCE = 1.5;  // x1.5 for each extra source covering the same story
const MAX_PER_SOURCE = 5;
const MAX_STORIES = 20;

// ---------- Helpers ----------
const STOPWORDS = new Set(['the', 'and', 'for', 'with', 'that', 'this', 'from', 'into', 'its',
  'are', 'was', 'has', 'have', 'how', 'why', 'what', 'new', 'now', 'after', 'over', 'about',
  'says', 'will', 'can', 'just', 'more', 'than', 'your', 'you', 'out', 'not', 'but']);

const wordsOf = (text) => text.toLowerCase().split(/[^a-z0-9-]+/).filter(Boolean);

// Sum of keyword weights found in the title.
const relevanceOf = (title) => {
  const lower = title.toLowerCase();
  const words = new Set(wordsOf(title));
  let total = 0;
  for (const [k, w] of Object.entries(KEYWORDS)) {
    if (k.includes(' ') ? lower.includes(k) : words.has(k)) total += w;
  }
  return total;
};

// 1.0 for brand new, 0.5 at HALF_LIFE_HOURS, 0.25 at twice that, ...
const freshnessOf = (published) => {
  const ageHours = published
    ? Math.max(0, (Date.now() - published) / 3.6e6)
    : MISSING_DATE_HOURS;
  return Math.pow(0.5, ageHours / HALF_LIFE_HOURS);
};

// HN/Lobsters points as a gentle boost: 10 -> x1.35, 100 -> x1.67, 1000 -> x2. RSS -> x1.
const popularityOf = (points) =>
  points == null ? 1 : 1 + Math.log10(points + 1) / 3;

const toTime = (value) => {
  const t = Date.parse(value);
  return Number.isNaN(t) ? null : t;
};

// Significant words used to spot the same story across sources.
const keyWordsOf = (title) =>
  new Set(wordsOf(title).filter(w => w.length >= 3 && !STOPWORDS.has(w)));

const isSameStory = (a, b) => {
  let shared = 0;
  for (const w of a) if (b.has(w)) shared++;
  return shared >= 3 && shared / Math.min(a.size, b.size) >= 0.5;
};

// ---------- Collect ----------
// Each item from "Fetch source" is either a story or a failure marker.
const expected = $('Source list').all().map(i => i.json.name);
const stories = [];
const errors = {};

$input.all().forEach((item, index) => {
  const j = item.json || {};
  if (j.failed) {
    errors[j.source] = j.error;
  } else if (j.error) {
    // The sub-workflow itself crashed: find which source it was for.
    const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
    const name = expected[p?.item ?? -1] || 'Unknown source';
    errors[name] = typeof j.error === 'string' ? j.error : (j.error.message || 'Sub-workflow failed');
  } else if (j.title && j.url && j.source) {
    stories.push(j);
  }
});

// A source counts as failed if none of its stories arrived.
const delivered = new Set(stories.map(s => s.source));
const failed = expected.filter(name => !delivered.has(name));
const failedDetails = failed.map(name => ({ source: name, error: errors[name] || 'No stories returned' }));

// ---------- Score each story ----------
const seenUrls = new Set();
const candidates = [];
for (const s of stories) {
  if (!s.title || !s.url || seenUrls.has(s.url)) continue;
  seenUrls.add(s.url);
  const relevance = relevanceOf(s.title);
  if (relevance === 0) continue; // not about your interests
  candidates.push({
    ...s,
    relevance,
    freshness: freshnessOf(s.published),
    popularity: popularityOf(s.points),
    keyWords: keyWordsOf(s.title),
  });
}

// ---------- Group the same story across sources ----------
const clusters = [];
for (const c of candidates) {
  const match = clusters.find(cl => cl.members.some(m => isSameStory(m.keyWords, c.keyWords)));
  if (match) match.members.push(c);
  else clusters.push({ members: [c] });
}

const ranked = clusters.map(({ members }) => {
  // Best individual story represents the group.
  const base = (m) => m.relevance * m.freshness * m.popularity;
  const lead = members.reduce((a, b) => (base(b) > base(a) ? b : a));
  const sources = [...new Set(members.map(m => m.source))];

  const relevance = Math.max(...members.map(m => m.relevance));
  const freshness = Math.max(...members.map(m => m.freshness));
  const popularity = Math.max(...members.map(m => m.popularity));
  const buzz = Math.pow(BUZZ_PER_SOURCE, sources.length - 1);

  return {
    title: lead.title,
    url: lead.url,
    source: [lead.source, ...sources.filter(s => s !== lead.source)].join(' + '),
    leadSource: lead.source,
    score: Math.round(relevance * freshness * popularity * buzz * 100) / 100,
    breakdown: {
      relevance,
      freshness: Math.round(freshness * 100) / 100,
      popularity: Math.round(popularity * 100) / 100,
      buzz: Math.round(buzz * 100) / 100,
    },
    published: lead.published ? new Date(lead.published).toISOString() : null,
    alsoAt: members.filter(m => m !== lead).map(m => m.url),
  };
});

// ---------- Pick the top stories ----------
ranked.sort((a, b) => b.score - a.score);

const perSource = {};
const top = [];
for (const s of ranked) {
  const n = perSource[s.leadSource] || 0;
  if (n >= MAX_PER_SOURCE) continue;
  perSource[s.leadSource] = n + 1;
  top.push(s);
  if (top.length >= MAX_STORIES) break;
}

return [{ json: { count: top.length, stories: top, failed, failedDetails } }];

const { stories } = $('Filter and Rank').first().json;
let content = $input.first().json.choices?.[0]?.message?.content || '';

// Drop any reasoning the model wrapped in <think> tags.
content = content.replace(/<think>[\s\S]*?<\/think>/g, '');

// Find the last valid JSON array of picks in the reply.
const parsePicks = (text) => {
  const end = text.lastIndexOf(']');
  if (end === -1) return null;
  let start = text.lastIndexOf('[', end);
  while (start !== -1) {
    try {
      const arr = JSON.parse(text.slice(start, end + 1));
      if (Array.isArray(arr) && arr.length && arr.every(p => p && p.id && p.summary)) return arr;
    } catch (e) {}
    if (start === 0) break;
    start = text.lastIndexOf('[', start - 1);
  }
  return null;
};

const used = new Set();
const picks = (parsePicks(content) || [])
  .map(p => ({ story: stories[Number(p.id) - 1], summary: String(p.summary).trim() }))
  .filter(p => p.story && !used.has(p.story.url) && used.add(p.story.url))
  .slice(0, 10);

let body;
if (picks.length) {
  body = picks
    .map((p, i) => `${i + 1}. ${p.story.title} (${p.story.source})\n${p.summary}\n${p.story.url}`)
    .join('\n\n');
} else {
  // LLM failed, was cut off, or returned junk: send the plain list instead.
  body = stories
    .map((s, i) => `${i + 1}. ${s.title} (${s.source})\n${s.url}`)
    .join('\n\n');
}

const date = new Date().toLocaleDateString('sv-SE');
return [{ json: { subject: `Tech digest ${date}`, text: body } }];

return [
  { name: 'Hacker News',  type: 'json', url: 'https://hn.algolia.com/api/v1/search?tags=front_page&hitsPerPage=30' },
  { name: 'Lobsters',     type: 'json', url: 'https://lobste.rs/hottest.json' },
  { name: 'TechCrunch',   type: 'rss',  url: 'https://techcrunch.com/feed/' },
  { name: 'The Register', type: 'rss',  url: 'https://www.theregister.com/headlines.atom' },
].map(json => ({ json }));
